@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------------------------------------------------------------------------
   View transitions
   ------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* Keep the page interactive while a transition runs: the ::view-transition
   overlay captures pointer events, so let them pass through to the live page. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element morph ---------------------------------------------------
   The product thumbnail and the detail hero share a view-transition-name
   (product-<slug>). The browser animates size/position between them with no
   extra CSS, but we soften the mid-flight interpolation with a brief blur. */
::view-transition-group(.morph) {
  animation-duration: 400ms;
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal --------------------------------------------------------
   The skeleton exits (slides down + fades out) and the real content enters
   (slides up + fades in). Asymmetric timing: the exit is fast so the
   placeholder yields quickly; the enter is slower and delayed until the
   exit completes so the user can register the new content. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}
@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* --- Directional navigation slides -----------------------------------------
   Forward navigation (grid -> detail) slides content left; back navigation
   (detail -> grid) slides content right. A small 60px offset communicates
   direction without forcing the user to track a fast-moving element. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
